export interface Record {
    id: string;
    amount: number;
    currency: string;
}

export function summarize(path: string): Summary {
    const text = readFileSync(path, "utf8");
    const lines = text.split("\n");
    let count = 0;
    let total = 0;
    for (const line of lines) {
        const record = parseLine(line);
        if (record === null) {
            continue;
        }
        count += 1;
        total += record.amount;
    }
    return { count, total };
}

export function filterByCurrency(records: Record[], currency: string): Record[] {
    const kept: Record[] = [];
    for (const record of records) {
        if (record.currency !== currency) {
            continue;
        }
        kept.push(record);
    }
    return kept;
}

